export const VIDEOS_BY_ID: Record<string, Video> = Object.fromEntries(VIDEOS.map((v) => [v.id, v]));

/** A reading's videos on Home: introducing its whole section, just before it, or after it (review). */
export function getVideosForReading(packId: string, position: Video["position"]): Video[] {
  return VIDEOS.filter((v) => v.packId === packId && v.position === position);
}
